#!/usr/bin/env python3
"""Render the reviewed dataset as a dependency-free interactive case study."""
import argparse,html,json
from pathlib import Path

def render(d,sample):
 m=d['metrics'];esc=html.escape
 cards=[]
 for a in d['apps']:
  fields=[('Authentication',', '.join(a['auth_methods'])+'. '+a.get('auth_notes','')),('Credential path',a['access']['notes']),('Sandbox',a['access']['sandbox']),('Production',a['access']['production']),('Plan gate',a['access']['plan_gate']),('Approval / role gate',a['access']['approval_gate']),('API',', '.join(a['api']['styles'])+'. '+a['api']['breadth']),('MCP',a['mcp']['status']+' / '+a['mcp'].get('scope','unknown')+'. '+a['mcp']['notes'])]
  body=''.join('<dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd>' for k,v in fields)
  links=''.join('<li><a target="_blank" rel="noopener" href="'+esc(e['url'],quote=True)+'">'+esc(e['title'])+'</a></li>'for e in a['evidence'])
  search=esc(json.dumps(a).lower(),quote=True)
  cards.append(f'<article data-verdict="{a["verdict"]}" data-category="{esc(a["category"],quote=True)}" data-search="{search}"><small>{a["number"]} / {esc(a["category"])} / {a["confidence"]} confidence</small><h3>{esc(a["name"])}</h3><p>{esc(a["description"])}</p><strong>{a["verdict"]} · {a["access"]["credential_path"].replace("_"," ")}</strong><p>{esc(a["blocker"])}</p><details><summary>Auth, access, API and evidence</summary><dl>{body}</dl><ul>{links}</ul></details></article>')
 def bars(values,total):
  return ''.join(f'<div class="bar"><span>{esc(k.replace("_"," "))}</span><b>{v} / {total}</b><i style="width:{100*v/total}%"></i></div>'for k,v in sorted(values.items(),key=lambda x:-x[1]))
 cats=''.join(f'<div class="panel"><h3>{esc(k)}</h3><p><b>{v["ready"]} of {v["apps"]} ready</b> · {v["conditional"]} conditional · {v["blocked"]} blocked</p></div>'for k,v in m['categories'].items())
 checks=''.join('<li><b>'+esc(x['app_id'])+' / '+esc(x['outcome'].replace('_',' '))+'</b><p>'+esc(x['claim_checked'])+'</p><a href="'+esc(x['source_url'],quote=True)+'" target="_blank" rel="noopener">Source checked</a></li>'for x in sample['checks'])
 categories=''.join('<option>'+esc(x)+'</option>'for x in m['categories'])
 return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Which apps are ready for agents?</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4efec;color:#251f21;font:16px/1.6 system-ui,sans-serif}main{max-width:1080px;background:white;margin:auto;padding:48px}h1,h2{font-family:Georgia,serif;font-weight:400;line-height:1.15}h1{font-size:48px;max-width:700px}h2{font-size:30px;margin:56px 0 24px}h3{font-size:19px;line-height:1.4}a{color:#235e50;overflow-wrap:anywhere}p{max-width:80ch}small,.quiet{color:#585254}section{margin:30px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.panel,.stat{border:1px solid #eae9ea;border-radius:8px;padding:20px;min-width:0}.stat b{display:block;font-size:36px}.note{background:#f4efec;padding:20px;border-radius:8px;margin:24px 0}article{border-top:1px solid #eae9ea;padding:24px 0;overflow-wrap:anywhere}article h3{font-size:23px}summary{min-height:44px;cursor:pointer;font-weight:600;padding:8px 0}dt{font-weight:600;margin-top:16px}dd{margin:4px 0 16px}input,select,button{font:inherit;border:1px solid #ccc;border-radius:4px;padding:10px;min-height:44px;max-width:100%}.controls{display:flex;flex-wrap:wrap;gap:10px}.bar{position:relative;padding:10px 8px;margin:8px 0;display:flex;justify-content:space-between;gap:12px;isolation:isolate}.bar i{position:absolute;inset:0 auto 0 0;background:#dfece7;z-index:-1;border-radius:4px}.bar span{overflow-wrap:anywhere}.bar b{white-space:nowrap}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4efec;padding:20px;font-size:13px}.sample li{margin:20px 0}footer{border-top:1px solid #eae9ea;margin-top:48px;padding-top:24px;color:#585254}nav a{margin-right:20px}@media(max-width:700px){main{padding:24px}h1{font-size:34px}.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.stat{padding:14px}.stat b{font-size:30px}.bar{font-size:14px}}
</style><main><small>PRIMARY-DOCUMENT AUDIT · 23 NOVEMBER 2026</small><h1>Which apps are ready for agents?</h1><p>The API is rarely the whole answer. Credential scope, production approval and product policy decide whether an agent can actually use it.</p><nav><a href="#findings">Findings</a><a href="#matrix">100-app matrix</a><a href="#method">Pipeline</a><a href="#verification">Verification</a></nav>'''+f'''
<section class="stats"><div class="stat"><b>{m['apps']}</b>apps researched</div><div class="stat"><b>{m['evidence_urls']}</b>primary URLs</div><div class="stat"><b>{m['verdicts']['ready']}</b>ready prototypes</div><div class="stat"><b>{m['mcp_scopes']['operational']}</b>operational MCP</div></section><div class="note">Researcher-selected, balanced 100-app benchmark across five categories. The referenced employer list was not visible, and own selection was approved. Findings are documented feasibility, not tested account access.</div>
<section id="findings"><h2>Build the easy path. Queue the gate.</h2><div class="grid"><div class="panel"><h3>Credential access</h3>{bars(m['credential_paths'],100)}<p class="quiet">One primary path per app. Free credentials do not mean free production access.</p></div><div class="panel"><h3>Toolkit verdict</h3>{bars(m['verdicts'],100)}<p class="quiet">Ready: scoped own-account prototype. Conditional: material entitlement, review or policy gate. Blocked: no viable new-onboarding path established.</p></div></div>
<h2>Vendor MCP ownership is only the first gate.</h2>{bars(m['mcp_scopes'],100)}<p>{m['mcp']['official']} apps have official MCP references, but only {m['mcp_scopes']['operational']} are classified as operational business-data/action interfaces. Preview, read-only and docs servers need different toolkit promises. Operational does not mean unrestricted or free.</p>
<h2>Where the first prototypes fit</h2><div class="grid">{cats}</div><p>OAuth appears in {m['auth_support_counts']['OAuth']} apps, tokens in {m['auth_support_counts']['Token']} and API keys in {m['auth_support_counts']['API key']}. Methods overlap. 81 apps have free or trial credentials, but only 38 earn a ready verdict.</p><div class="note"><b>Start here:</b> GitHub, Linear, Supabase and Todoist are documented scoped-prototype candidates. Give paid/admin/partner gates an operations queue. Do not start new Opsgenie onboarding.</div>
<div class="grid"><div class="panel"><h3>API and MCP access differ</h3><p>New Relic offers a free account/API route but requires paid plans for hosted MCP. Notion interactive and unattended MCP have different plan rules.</p></div><div class="panel"><h3>A token can be valid but wrong</h3><p>GitLab MCP rejects legacy PATs and project/group tokens that work for REST. Model auth per interface, not per brand.</p></div><div class="panel"><h3>Lifecycle beats old docs</h3><p>Opsgenie API docs remain online, but signups ended 4 June 2025 and access ends 5 April 2027.</p></div><div class="panel"><h3>Sandbox is not production</h3><p>Plaid sandbox access, Xero demo organizations and Google Ads test access are useful starts, not blanket production entitlements.</p></div></div></section>
<section id="matrix"><h2>Every app, with its conditions</h2><div class="controls"><input id="q" aria-label="Search apps, evidence or blockers" placeholder="Search apps, evidence or blockers"><select id="verdict" aria-label="Verdict"><option value="all">All verdicts</option><option>ready</option><option>conditional</option><option>blocked</option><option>unknown</option></select><select id="category" aria-label="Category"><option>All categories</option>{categories}</select><button id="reset" type="button">Reset filters</button></div><p id="count" aria-live="polite">100 of 100 apps</p><div id="apps">{''.join(cards)}</div><p id="empty" hidden>No matches. Reset filters to return to the full benchmark.</p></section>
<section id="method"><h2>An executable evidence pipeline</h2><ol><li>Discover relevant primary documentation using confirmed official-domain allowlists.</li><li>Collect public pages into dated content-hashed snapshots. Preserve retrieval and robots failures.</li><li>Extract candidate claims, then challenge negation, scope, environment and MCP ownership.</li><li>Review with source context. Validate the complete schema and derive aggregates from rows.</li><li>Generate a risk review queue, record actual corrections and label human checks separately.</li></ol><pre>python -m unittest discover -s tests -v
python src/finalize.py --input data/full/*.json --output output/final --expected-count 100
python src/build_report.py --dataset output/final/dataset.json --output output/report.html
python src/verify_sources.py --dataset output/final/dataset.json --output output/source-verification</pre><div class="note"><b>What actually ran:</b> AI-assisted primary-document research, not an unattended 100-app LLM batch. The collector, discovery guards, replay, schema, aggregation and report utilities were executed. Weak keyless search and failed pages remain recorded. No paid accounts, app installs, production actions or Composio SDK execution are claimed.</div></section>
<section id="verification"><h2>Corrections without invented accuracy</h2><div class="grid"><div class="panel"><h3>407 URLs replayed</h3><p>372 retrieved; 20 fetch errors; five robots files unavailable; 10 robots disallowed. This is retrieval health, not 91% research accuracy.</p></div><div class="panel"><h3>20 risk-focused checks</h3><p>Four apps per category. Each checks one material claim. This is AI source review, not random sampling or independent human review.</p></div></div><details><summary>Open the 20-app source challenge sample</summary><ol class="sample">{checks}</ol></details><div class="grid"><div class="panel"><h3>Help Scout: free vs trial</h3><p>The official MCP guide limits API access to Standard, Plus and Pro. Corrected free-self-serve classification to trial path; verdict conditional.</p></div><div class="panel"><h3>HubSpot: remote MCP scope</h3><p>A broad read/write draft claim was corrected against the current remote MCP guide, which describes read-only standard CRM records.</p></div><div class="panel"><h3>GitHub: Basic is endpoint-scoped</h3><p>A Basic-auth keyword candidate was narrowed to selected app endpoints rather than general username/password API access.</p></div><div class="panel"><h3>Ecwid: aggregator is not ownership</h3><p>A third-party catalog was removed as proof of an official vendor MCP server. The current row says not confirmed.</p></div></div><p>Actual changes are recorded in the source correction ledger. Miro plan conflicts, Ecwid old plan names and inaccessible pages remain visible limitations. No independent reference labels exist, so no before/after accuracy percentage is invented.</p><div class="note"><b>A person still needs to check:</b> completed independent human checks remain zero. The assignment asks for human verification and code understanding. The source includes a short checklist; the candidate should complete it before submitting.</div></section><footer>Researched 23 November 2026. Own app selection. Public-document evidence only. No guarantee of production approval. No application submission is performed from this page.</footer></main>
<script>
const q=document.getElementById('q'),v=document.getElementById('verdict'),c=document.getElementById('category'),rows=[...document.querySelectorAll('#apps article')];
function filter(){{let n=0;for(const r of rows){{let ok=r.dataset.search.includes(q.value.toLowerCase())&&(v.value==='all'||r.dataset.verdict===v.value)&&(c.value==='All categories'||r.dataset.category===c.value);r.hidden=!ok;n+=ok}}document.getElementById('count').textContent=n+' of '+rows.length+' apps';document.getElementById('empty').hidden=n>0}}
q.addEventListener('input',filter);v.addEventListener('change',filter);c.addEventListener('change',filter);document.getElementById('reset').onclick=()=>{{q.value='';v.value='all';c.value='All categories';filter()}};
</script></html>'''

def main():
 p=argparse.ArgumentParser();p.add_argument('--dataset',required=True);p.add_argument('--sample',default='data/review/risk-sample.json');p.add_argument('--output',required=True);a=p.parse_args();d=json.loads(Path(a.dataset).read_text());s=json.loads(Path(a.sample).read_text());out=Path(a.output);out.parent.mkdir(parents=True,exist_ok=True);out.write_text(render(d,s));print(out)
if __name__=='__main__':main()
